const envelope=$json.body ?? $json;
const pasted=typeof envelope.json==='string' ? envelope.json.trim() : '';
const binary=$input.item.binary ?? {};
const fileKey=binary.json_file ? 'json_file' : null;
if(pasted && fileKey) throw new Error('Entrega el MASTER de una sola forma: pega el JSON o sube un archivo .json, no ambos.');
if(!pasted && !fileKey) throw new Error('Falta el MASTER JSON. Pégalo o sube un archivo .json.');
let raw=pasted;
if(fileKey){
  const meta=binary[fileKey] ?? {};
  if(meta.fileName && !/\.json$/i.test(String(meta.fileName))) throw new Error('El archivo subido debe tener extensión .json.');
  raw=(await this.helpers.getBinaryDataBuffer(0,fileKey)).toString('utf8').replace(/^\uFEFF/,'').trim();
}
let master;
try { master=JSON.parse(raw); } catch(error) { throw new Error(`El MASTER no contiene JSON válido: ${error.message}`); }
if(typeof master==='string'){ try { master=JSON.parse(master.trim()); } catch(error) { throw new Error(`El JSON anidado no es válido: ${error.message}`); } }
const str=value=>value===null||value===undefined?'':String(value).trim();
const control=str(master?.CONTROL_EDITORIAL?.ESTADO ?? master?.control_editorial?.estado).toUpperCase();
if(control!=='LISTO') throw new Error(`CONTROL_EDITORIAL.ESTADO debe ser LISTO; se recibió: ${control||'(vacío)'}.`);
const content=str(master.GUTENBERG_ENRIQUECIDO_FINAL ?? master.gutenberg_enriquecido_final);
if(!content) throw new Error('Falta GUTENBERG_ENRIQUECIDO_FINAL.');
const forbidden=[/opmx-editorial/i,/data-opmx/i,/<!--\s*wp:html/i,/<\/?(?:article|header|footer)\b/i,/<h1\b/i,/\{\{OPMX:/i];
if(forbidden.some(rx=>rx.test(content))) throw new Error('GUTENBERG_ENRIQUECIDO_FINAL contiene wrappers, marcadores o tokens MEDIA no permitidos.');
const names=[...content.matchAll(/<!--\s*\/?wp:([a-z0-9/-]+)/gi)].map(m=>m[1].replace(/^core\//,''));
const allowed=new Set(['paragraph','heading','list','quote','image']);
if(!names.length || names.some(name=>!allowed.has(name))) throw new Error(`GUTENBERG_ENRIQUECIDO_FINAL usa bloques no autorizados: ${[...new Set(names.filter(name=>!allowed.has(name)))].join(', ')||'(sin bloques)'}.`);
if(/<!--\s*wp:image/i.test(content) && (!/\bwp-image-\d+\b/i.test(content) || !/\balt=(['"]).*?\1/i.test(content))) throw new Error('Cada core/image debe enlazar un adjunto nativo wp-image-{id} y conservar ALT literal.');
const rawId=master.OPURO_POST_ID ?? master.POST_ID ?? master?.PUBLICACION?.WP_POST_ID ?? master?.PUBLICACION?.POST_ID ?? master?.OPURO_UPDATE?.POST_ID;
const post_id=Number(rawId);
if(!Number.isInteger(post_id)||post_id<=0) throw new Error('Falta un post_id válido. Añade OPURO_POST_ID al MASTER (o PUBLICACION.POST_ID / PUBLICACION.WP_POST_ID). No se hará ninguna escritura.');
const expected_slug=str(master?.SEO?.SLUG ?? master?.seo?.slug);
if(expected_slug && !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(expected_slug)) throw new Error('SEO.SLUG no es válido para usarlo como blindaje del post destino.');
return {json:{post_id,expected_slug,gutenberg_enriquecido_final:content,master_title:str(master?.SEO?.TITULO_SEO ?? master?.TEXTO_EDITORIAL?.TITULO),contract_state:control},binary};

const packageData=$('OPURO — Validar paquete de actualización').first().json;
const post=$json;
if(Number(post?.id)!==Number(packageData.post_id)) throw new Error('El CMS devolvió un post distinto al post_id solicitado.');
if(post?.type!=='post') throw new Error('El destino no es una entrada estándar de WordPress.');
if(!['draft','publish','pending','future','private'].includes(String(post?.status??''))) throw new Error(`Estado no actualizable: ${post?.status??'(vacío)'}.`);
const currentSlug=String(post?.slug??'').trim();
if(!currentSlug) throw new Error('El post destino no tiene slug.');
if(packageData.expected_slug && currentSlug!==packageData.expected_slug) throw new Error(`Blindaje anti-destino equivocado: el paquete indica slug ${packageData.expected_slug} y el post ${post.id} tiene ${currentSlug}.`);
const snapshot={id:Number(post.id),slug:currentSlug,status:String(post.status),author:Number(post.author),date:String(post.date??''),categories:Array.isArray(post.categories)?post.categories.map(Number).sort((a,b)=>a-b):[],tags:Array.isArray(post.tags)?post.tags.map(Number).sort((a,b)=>a-b):[],featured_media:Number(post.featured_media??0)};
return {json:{...packageData,before:snapshot}};

const context=$('OPURO — Blindaje preactualización').first().json;
const post=$json;
const before=context.before;
const normalized=value=>String(value??'').replace(/\r\n/g,'\n').trim();
if(Number(post?.id)!==before.id) throw new Error('Readback inválido: cambió el ID.');
const after={slug:String(post?.slug??''),status:String(post?.status??''),author:Number(post?.author),date:String(post?.date??''),categories:Array.isArray(post.categories)?post.categories.map(Number).sort((a,b)=>a-b):[],tags:Array.isArray(post.tags)?post.tags.map(Number).sort((a,b)=>a-b):[],featured_media:Number(post.featured_media??0)};
for(const key of ['slug','status','author','date','categories','tags','featured_media']){ if(JSON.stringify(after[key])!==JSON.stringify(before[key])) throw new Error(`Readback rechazado: cambió ${key}, que este Publisher no tiene autorización para modificar.`); }
const stored=normalized(post?.content?.raw);
const intended=normalized(context.gutenberg_enriquecido_final);
if(stored!==intended) throw new Error('Readback rechazado: WordPress no conservó exactamente el Gutenberg enriquecido esperado.');
return {json:{...context,post_status:after.status,slug:after.slug,public_url:after.status==='publish'?`https://oxigenopuro.com.mx/${encodeURIComponent(after.slug)}/`:null,edit_url:`${$vars.OPMX_OPURO_WP_BASE_URL}/wp-admin/post.php?post=${before.id}&action=edit`}};

const context=$('OPURO — Verificar actualización content-only').first().json;
const revalidation=$('OPURO — Invalidar caché de nota').first().json;
return {json:{status:'SUCCESS',workflow:'OPMX OPURO Content Update v1.0',target:'oxigenopuro',post_id:context.post_id,post_status:context.post_status,slug:context.slug,public_url:context.public_url,edit_url:context.edit_url,content_updated:true,unchanged:['slug','status','author','date','categories','tags','featured_media','SEO','media'],cache_revalidation:{status:revalidation?.revalidated===true?'SUCCESS':'NOT_CONFIRMED',tags:revalidation?.tags??[],paths:revalidation?.paths??[]},warnings:[]}};
